window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-171fc6786733f113"]={"versions": [{"id": "FIG-171fc6786733f113", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der Schnittstellenarchitektur des Funktionsclusters <code>Registry</code> innerhalb der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Bereitstellung der internen Plattform-Schnittstelle <code>Manifest Accessor</code> durch die <code>Registry</code> sowie deren statische Verwendungsbeziehungen (<code>«use»</code>) durch weitere funktionale Cluster der Plattform-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Realisierende Komponente:\n<ul class=\"fig-list\"><li><code>Registry</code> («aapFunctionalCluster») implementiert über eine gestrichelte Realisierungsbeziehung mit geschlossenem Hohlpfeil die interne native Schnittstelle.\n</li></ul>\n</li><li>Schnittstelle:\n<ul class=\"fig-list\"><li><code>Manifest Accessor</code> («aapInternal,aapNativeInterface»).\n</li></ul>\n</li><li>Verwendende funktionale Cluster («aapFunctionalCluster...» bzw. «aapFunctionalCluster»):\n<ul class=\"fig-list\"><li><code>Communication Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Network Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Time Synchronization</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Stereotyp «aapFunctionalCluster», Verwendung über <code>«use»</code>)\n</li><li><code>Cryptography</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Diagnostic Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Execution Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Platform Health Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Persistency</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Identity and Access Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Log and Trace</code> (Verwendung über <code>«use»</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle aufrufenden Komponenten greifen über gerichtete Abhängigkeitspfeile mit Stereotyp <code>«use»</code> auf das Interface <code>Manifest Accessor</code> zu.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Verhaltens- oder Sequenzablaufspezifikation. Die gerichteten Abhängigkeiten (<code>«use»</code>) modellieren lesende bzw. abfragende Zugriffe der funktionalen Cluster auf Manifest-Informationen, die zentral über die Manifest-Accessor-Schnittstelle der Registry bereitgestellt werden. Laufzeitabhängigkeiten, Aufrufprotokolle oder Initialisierungsreihenfolgen zwischen Daemon-Prozessen und Bibliotheken sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die AUTOSAR Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Die Schnittstelle <code>Manifest Accessor</code> ist rein plattformintern (<code>«aapInternal»</code>) und als native C++-Programmierschnittstelle (<code>«aapNativeInterface»</code>) ausgeführt. Sie steht Anwendungsprozessen außerhalb der funktionalen Cluster nicht direkt zur Verfügung.\n</li><li>Sieben der elf nutzenden Funktionscluster sind explizit als <code>daemon-based</code> ausgewiesen, was bei der Implementierung auf eigenständige Hintergrundprozesse hinweist.\n</li><li>Implementierer funktionaler Cluster müssen zur Auswertung von Manifest-Daten die von der Registry implementierte native Schnittstelle einbinden, anstatt Manifeste autark einzulesen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6325b6c0985d4914", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der Schnittstellenarchitektur des Funktionsclusters <code>Registry</code> innerhalb der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Bereitstellung der internen Plattform-Schnittstelle <code>Manifest Accessor</code> durch die <code>Registry</code> sowie deren statische Verwendungsbeziehungen (<code>«use»</code>) durch weitere funktionale Cluster der Plattform-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Realisierende Komponente:\n<ul class=\"fig-list\"><li><code>Registry</code> («aapFunctionalCluster») implementiert über eine gestrichelte Realisierungsbeziehung mit geschlossenem Hohlpfeil die Schnittstelle.\n</li></ul>\n</li><li>Schnittstelle:\n<ul class=\"fig-list\"><li><code>ManifestAccessor</code> («aapInternal,aapNativeInterface»).\n</li></ul>\n</li><li>Verwendende funktionale Cluster («aapFunctionalCluster...» bzw. «aapFunctionalCluster»):\n<ul class=\"fig-list\"><li><code>Communication Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Network Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Time Synchronization</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Stereotyp «aapFunctionalCluster», Verwendung über <code>«use»</code>)\n</li><li><code>Cryptography</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Diagnostic Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Execution Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Platform Health Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Persistency</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Identity and Access Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Log and Trace</code> (Verwendung über <code>«use»</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle elf nutzenden funktionalen Cluster greifen über gerichtete Abhängigkeitsrelationen (<code>«use»</code>) auf <code>ManifestAccessor</code> zu.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Verhaltens- oder Sequenzablaufspezifikation. Die gerichteten Abhängigkeiten (<code>«use»</code>) modellieren lesende bzw. abfragende Zugriffe der funktionalen Cluster auf Manifest-Informationen, die zentral über die Manifest-Accessor-Schnittstelle der Registry bereitgestellt werden. Laufzeitabhängigkeiten, Aufrufprotokolle oder Initialisierungsreihenfolgen zwischen Daemon-Prozessen und Bibliotheken sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die AUTOSAR Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Die Schnittstelle <code>ManifestAccessor</code> ist rein plattformintern (<code>«aapInternal»</code>) und als native C++-Programmierschnittstelle (<code>«aapNativeInterface»</code>) ausgeführt. Sie steht Anwendungsprozessen außerhalb der Plattformkomponenten nicht zur Verfügung.\n</li><li>Sieben der elf nutzenden Funktionscluster sind explizit als <code>daemon-based</code> ausgewiesen.\n</li><li>Implementierer funktionaler Cluster greifen zur Auswertung von Manifest-Daten auf die einheitlich benannte Schnittstelle <code>ManifestAccessor</code> zu.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-58269fa3c6bd057a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der Schnittstellenarchitektur der Komponente <code>Registry</code> innerhalb der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Bereitstellung der internen Plattform-Schnittstelle <code>ManifestAccessor</code> durch die <code>Registry</code> sowie deren Verwendungsbeziehungen (<code>«use»</code>) durch funktionale Cluster der Plattform-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Realisierende Komponente:\n<ul class=\"fig-list\"><li><code>Registry</code> (ohne Stereotyp-Annotation, hellbeige hinterlegt) implementiert über eine gestrichelte Realisierungsbeziehung die Schnittstelle <code>ManifestAccessor</code>.\n</li></ul>\n</li><li>Schnittstelle:\n<ul class=\"fig-list\"><li><code>ManifestAccessor</code> («aapInternal,aapNativeInterface»).\n</li></ul>\n</li><li>Verwendende funktionale Cluster («aapFunctionalCluster...» bzw. «aapFunctionalCluster»):\n<ul class=\"fig-list\"><li><code>Communication Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Network Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Time Synchronization</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Stereotyp «aapFunctionalCluster», Verwendung über <code>«use»</code>)\n</li><li><code>Cryptography</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Diagnostic Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Execution Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Platform Health Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Persistency</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Vehicle Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Log and Trace</code> (Verwendung über <code>«use»</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle elf abhängigen Komponenten greifen über gerichtete Abhängigkeitspfeile (<code>«use»</code>) auf die zentrale Schnittstelle <code>ManifestAccessor</code> zu.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Verhaltens- oder Sequenzablaufspezifikation. Die gerichteten Abhängigkeiten (<code>«use»</code>) modellieren lesende bzw. abfragende Zugriffe der funktionalen Cluster auf Manifest-Informationen, die zentral über die Manifest-Accessor-Schnittstelle der Registry bereitgestellt werden. Laufzeitabhängigkeiten, Aufrufprotokolle oder Initialisierungsreihenfolgen zwischen Daemon-Prozessen und Bibliotheken sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die AUTOSAR Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Die Schnittstelle <code>ManifestAccessor</code> ist plattformintern (<code>«aapInternal»</code>) und nativ typisiert (<code>«aapNativeInterface»</code>).\n</li><li>Acht der elf nutzenden Cluster (<code>Communication Management</code>, <code>Time Synchronization</code>, <code>Update and Configuration Management</code>, <code>Cryptography</code>, <code>Diagnostic Management</code>, <code>Execution Management</code>, <code>Platform Health Management</code>, <code>Vehicle Update and Configuration Management</code>) sind explizit als prozessbasierte Hintergrunddienste (<code>daemon-based</code>) spezifiziert.\n</li><li><code>Vehicle Update and Configuration Management</code> greift wie die übrigen Cluster auf <code>ManifestAccessor</code> zu; <code>Identity and Access Management</code> ist nicht als Konsument angebunden.\n</li><li>Die Komponente <code>Registry</code> trägt im Gegensatz zu den interagierenden Clustern kein Cluster-Stereotyp.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-33bd21b925913cc1", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der Schnittstellenarchitektur der Komponente <code>Registry</code> innerhalb der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Bereitstellung der internen Plattform-Schnittstelle <code>ManifestAccessor</code> durch die <code>Registry</code> sowie deren Verwendungsbeziehungen (<code>«use»</code>) durch funktionale Cluster der Plattform-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Realisierende Komponente:\n<ul class=\"fig-list\"><li><code>Registry</code> (ohne Stereotyp-Annotation, hellbeige hinterlegt) implementiert über eine gestrichelte Realisierungsbeziehung die Schnittstelle <code>ManifestAccessor</code>.\n</li></ul>\n</li><li>Schnittstelle:\n<ul class=\"fig-list\"><li><code>ManifestAccessor</code> («aapInternal,aapNativeInterface»).\n</li></ul>\n</li><li>Verwendende funktionale Cluster («aapFunctionalCluster...» bzw. «aapFunctionalCluster»):\n<ul class=\"fig-list\"><li><code>Communication Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Network Management</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Time Synchronization</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Stereotyp «aapFunctionalCluster», Verwendung über <code>«use»</code>)\n</li><li><code>Cryptography</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Diagnostic Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Execution Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Platform Health Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Persistency</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Vehicle Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Log and Trace</code> (Verwendung über <code>«use»</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle elf abhängigen Komponenten greifen über gerichtete Abhängigkeitspfeile (<code>«use»</code>) auf die zentrale Schnittstelle <code>ManifestAccessor</code> zu.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Verhaltens- oder Sequenzablaufspezifikation. Die gerichteten Abhängigkeiten (<code>«use»</code>) modellieren lesende bzw. abfragende Zugriffe der funktionalen Cluster auf Manifest-Informationen, die zentral über die Manifest-Accessor-Schnittstelle der Registry bereitgestellt werden. Laufzeitabhängigkeiten, Aufrufprotokolle oder Initialisierungsreihenfolgen zwischen Daemon-Prozessen und Bibliotheken sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die AUTOSAR Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Die Schnittstelle <code>ManifestAccessor</code> ist plattformintern (<code>«aapInternal»</code>) und nativ typisiert (<code>«aapNativeInterface»</code>).\n</li><li>Acht der elf nutzenden Cluster (<code>Communication Management</code>, <code>Time Synchronization</code>, <code>Update and Configuration Management</code>, <code>Cryptography</code>, <code>Diagnostic Management</code>, <code>Execution Management</code>, <code>Platform Health Management</code>, <code>Vehicle Update and Configuration Management</code>) sind explizit als prozessbasierte Hintergrunddienste (<code>daemon-based</code>) spezifiziert.\n</li><li><code>Vehicle Update and Configuration Management</code> greift wie die übrigen Cluster auf <code>ManifestAccessor</code> zu; <code>Identity and Access Management</code> ist nicht als Konsument angebunden.\n</li><li>Die Komponente <code>Registry</code> trägt im Gegensatz zu den interagierenden Clustern kein Cluster-Stereotyp.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0c7db60b6e19a28f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der Schnittstellenarchitektur der Komponente <code>Registry</code> innerhalb der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Bereitstellung der internen Plattform-Schnittstelle <code>ManifestAccessor</code> durch die <code>Registry</code> sowie deren Verwendungsbeziehungen (<code>«use»</code>) durch funktionale Cluster der Plattform-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Realisierende Komponente:\n<ul class=\"fig-list\"><li><code>Registry</code> implementiert über eine gestrichelte Realisierungsbeziehung die Schnittstelle <code>ManifestAccessor</code>.\n</li></ul>\n</li><li>Schnittstelle:\n<ul class=\"fig-list\"><li><code>ManifestAccessor</code> («aapInternal,aapNativeInterface»).\n</li></ul>\n</li><li>Verwendende funktionale Cluster («aapFunctionalCluster...» bzw. «aapFunctionalCluster»):\n<ul class=\"fig-list\"><li><code>Communication Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Network Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Time Synchronization</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Stereotyp «aapFunctionalCluster», Verwendung über <code>«use»</code>)\n</li><li><code>Cryptography</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Diagnostic Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Execution Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Platform Health Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Persistency</code> (Verwendung über <code>«use»</code>)\n</li><li><code>Vehicle Update and Configuration Management</code> (gekennzeichnet als <code>daemon-based</code>, Verwendung über <code>«use»</code>)\n</li><li><code>Log and Trace</code> (Verwendung über <code>«use»</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle elf abhängigen Komponenten nutzen über gerichtete Pfeile mit Stereotyp <code>«use»</code> die Schnittstelle <code>ManifestAccessor</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Verhaltens- oder Sequenzablaufspezifikation. Die gerichteten Abhängigkeiten (<code>«use»</code>) modellieren lesende bzw. abfragende Zugriffe der funktionalen Cluster auf Manifest-Informationen, die zentral über die Manifest-Accessor-Schnittstelle der Registry bereitgestellt werden. Laufzeitabhängigkeiten, Aufrufprotokolle oder Initialisierungsreihenfolgen zwischen Daemon-Prozessen und Bibliotheken sind nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die AUTOSAR Adaptive Platform:</p>\n<ul class=\"fig-list\"><li>Die Schnittstelle <code>ManifestAccessor</code> ist plattformintern (<code>«aapInternal»</code>) und als native Schnittstelle (<code>«aapNativeInterface»</code>) definiert.\n</li><li>Neun der elf nutzenden Cluster (<code>Communication Management</code>, <code>Network Management</code>, <code>Time Synchronization</code>, <code>Update and Configuration Management</code>, <code>Cryptography</code>, <code>Diagnostic Management</code>, <code>Execution Management</code>, <code>Platform Health Management</code>, <code>Vehicle Update and Configuration Management</code>) sind explizit als prozessbasierte Hintergrunddienste (<code>daemon-based</code>) spezifiziert.\n</li><li><code>Persistency</code> und <code>Log and Trace</code> verbleiben ohne die Auszeichnung <code>daemon-based</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-171fc6786733f113", "to": "FIG-6325b6c0985d4914", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Zentrale Schnittstelle: Schreibweise von <code>Manifest Accessor</code> zu <code>ManifestAccessor</code> (CamelCase ohne Leerzeichen) korrigiert.\n</li></ul>"}, {"from": "FIG-6325b6c0985d4914", "to": "FIG-58269fa3c6bd057a", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Funktionaler Cluster <code>Registry</code>: Stereotyp <code>«aapFunctionalCluster»</code> entfernt; Hintergrundfarbe von Orange auf Hellbeige geändert.\n</li><li>Funktionaler Cluster <code>Communication Management</code>: Kennzeichnung <code>daemon-based</code> hinzugefügt.\n</li><li>Funktionaler Cluster <code>Identity and Access Management</code>: Element entfernt.\n</li><li>Funktionaler Cluster <code>Vehicle Update and Configuration Management</code>: Element mit Kennzeichnung <code>daemon-based</code> und Abhängigkeitspfad <code>«use»</code> auf <code>ManifestAccessor</code> neu eingefügt.\n</li></ul>"}, {"from": "FIG-58269fa3c6bd057a", "to": "FIG-33bd21b925913cc1", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-33bd21b925913cc1", "to": "FIG-0c7db60b6e19a28f", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Funktionaler Cluster <code>Network Management</code>: Kennzeichnung <code>daemon-based</code> hinzugefügt.\n</li></ul>"}]};
